import java.util.*;
interface ProductPlugin { String name(); String run(String id); }
class OrthoPlugin implements ProductPlugin { public String name(){ return "ortho"; } public String run(String id){ return "ORTHO:" + id; } }
class DemPlugin implements ProductPlugin { public String name(){ return "dem"; } public String run(String id){ return "DEM:" + id; } }
public class PluginPolymorphismDemo {
    public static void main(String[] args){
        List<ProductPlugin> plugins = List.of(new OrthoPlugin(), new DemPlugin());
        plugins.forEach(p -> System.out.println(p.run("T1")));
    }
}
